insert into public.questions (id, exam_id, order_index, content, options, category, tags) values
  (md5('mchat-1')::uuid, 'dddddddd-0000-0000-0000-000000000001', 0, 'Si usted señala algo al otro lado de la habitación, ¿su hijo(a) lo mira? (Por ejemplo, si señala un juguete o un animal).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-2')::uuid, 'dddddddd-0000-0000-0000-000000000001', 1, '¿Alguna vez se ha preguntado si su hijo(a) es sordo(a)?', '{"type":"yesno","yes_label":"Sí","yes_score":1,"no_label":"No","no_score":0}'::jsonb, 'Comunicación social', array['mchat','ítem inverso']::text[]),
  (md5('mchat-3')::uuid, 'dddddddd-0000-0000-0000-000000000001', 2, '¿Su hijo(a) juega a simular o hacer como si...? (Por ejemplo, beber de una taza vacía, fingir que habla por teléfono o darle de comer a un muñeco).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-4')::uuid, 'dddddddd-0000-0000-0000-000000000001', 3, '¿A su hijo(a) le gusta subirse a las cosas? (Por ejemplo, muebles, juegos del parque o escaleras).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-5')::uuid, 'dddddddd-0000-0000-0000-000000000001', 4, '¿Hace su hijo(a) movimientos inusuales con los dedos cerca de sus ojos? (Por ejemplo, mover o aletear los dedos cerca de sus ojos).', '{"type":"yesno","yes_label":"Sí","yes_score":1,"no_label":"No","no_score":0}'::jsonb, 'Comunicación social', array['mchat','ítem inverso']::text[]),
  (md5('mchat-6')::uuid, 'dddddddd-0000-0000-0000-000000000001', 5, '¿Su hijo(a) señala con un dedo para pedir algo o para pedir ayuda? (Por ejemplo, señalar un alimento o juguete fuera de su alcance).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-7')::uuid, 'dddddddd-0000-0000-0000-000000000001', 6, '¿Su hijo(a) señala con un dedo para mostrarle algo interesante? (Por ejemplo, señalar un avión en el cielo o un camión grande en la calle).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-8')::uuid, 'dddddddd-0000-0000-0000-000000000001', 7, '¿Su hijo(a) se interesa por otros niños? (Por ejemplo, mira a otros niños, les sonríe o se les acerca).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-9')::uuid, 'dddddddd-0000-0000-0000-000000000001', 8, '¿Su hijo(a) le muestra cosas trayéndoselas o sosteniéndolas para que usted las vea? (No sólo para pedir ayuda, sino para compartir su interés).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-10')::uuid, 'dddddddd-0000-0000-0000-000000000001', 9, '¿Su hijo(a) responde cuando usted le llama por su nombre? (Por ejemplo, ¿se gira, le mira o deja de hacer lo que estaba haciendo?).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-11')::uuid, 'dddddddd-0000-0000-0000-000000000001', 10, 'Cuando usted le sonríe a su hijo(a), ¿él o ella le devuelve la sonrisa?', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-12')::uuid, 'dddddddd-0000-0000-0000-000000000001', 11, '¿A su hijo(a) le molestan mucho ruidos cotidianos? (Por ejemplo, la aspiradora, licuadora o secador de pelo llorando o tapándose los oídos).', '{"type":"yesno","yes_label":"Sí","yes_score":1,"no_label":"No","no_score":0}'::jsonb, 'Comunicación social', array['mchat','ítem inverso']::text[]),
  (md5('mchat-13')::uuid, 'dddddddd-0000-0000-0000-000000000001', 12, '¿Su hijo(a) camina?', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-14')::uuid, 'dddddddd-0000-0000-0000-000000000001', 13, '¿Su hijo(a) le mira a los ojos cuando usted le habla, juega con él o le viste?', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-15')::uuid, 'dddddddd-0000-0000-0000-000000000001', 14, '¿Su hijo(a) intenta imitar lo que usted hace? (Por ejemplo, decir adiós con la mano, aplaudir o hacer un sonido divertido).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-16')::uuid, 'dddddddd-0000-0000-0000-000000000001', 15, 'Si usted se gira a mirar algo, ¿su hijo(a) gira la cabeza para ver qué está mirando usted?', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-17')::uuid, 'dddddddd-0000-0000-0000-000000000001', 16, '¿Su hijo(a) intenta hacer que usted le mire? (Por ejemplo, le busca la mirada para que le felicite o dice ''¡mira!'').', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-18')::uuid, 'dddddddd-0000-0000-0000-000000000001', 17, '¿Su hijo(a) comprende cuando usted le dice que haga algo sin hacer gestos? (Por ejemplo, ''pon el libro en la mesa'').', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-19')::uuid, 'dddddddd-0000-0000-0000-000000000001', 18, 'Si pasa algo nuevo, ¿su hijo(a) le mira a la cara para ver cómo reacciona usted? (Por ejemplo, si oye un ruido extraño).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[]),
  (md5('mchat-20')::uuid, 'dddddddd-0000-0000-0000-000000000001', 19, '¿Le gustan a su hijo(a) las actividades de movimiento? (Por ejemplo, que le balanceen o le hagan cosquillas).', '{"type":"yesno","yes_label":"Sí","yes_score":0,"no_label":"No","no_score":1}'::jsonb, 'Comunicación social', array['mchat']::text[])
insert into public.diagnostic_rules (id, exam_id, name, min_score, max_score, min_age, max_age, subcategory, recommendations, is_active) values
  (md5('mchat-rule-1')::uuid, 'dddddddd-0000-0000-0000-000000000001', 'Riesgo bajo de TEA (M-CHAT-R 0 a 2)', 0, 2, 1, 2, 'Riesgo bajo de TEA (M-CHAT-R 0 a 2)', '["Sin señales tempranas significativas. Repetir el tamizaje a los 24 meses si fue aplicado antes.","Continuar la vigilancia de hitos del desarrollo en controles pediátricos."]'::jsonb, true),
  (md5('mchat-rule-2')::uuid, 'dddddddd-0000-0000-0000-000000000001', 'Riesgo medio de TEA (M-CHAT-R 3 a 7)', 3, 7, 1, 2, 'Riesgo medio de TEA (M-CHAT-R 3 a 7)', '["Aplicar la entrevista de seguimiento M-CHAT-R/F con el especialista.","Si tras el seguimiento persisten 2 o más puntos, derivar a evaluación diagnóstica."]'::jsonb, true),
  (md5('mchat-rule-3')::uuid, 'dddddddd-0000-0000-0000-000000000001', 'Riesgo alto de TEA (M-CHAT-R 8 a 20)', 8, 20, 1, 2, 'Riesgo alto de TEA (M-CHAT-R 8 a 20)', '["Derivar a evaluación diagnóstica especializada sin esperar el seguimiento.","Iniciar orientación a la familia sobre intervención temprana.","El resultado es un tamizaje: el diagnóstico lo establece un profesional."]'::jsonb, true)
