insert into public.questions (id, exam_id, order_index, content, options, category, tags) values
  (md5('aq50-1')::uuid, 'dddddddd-0000-0000-0000-000000000002', 0, 'Prefiero hacer las cosas con otros que solo.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
  (md5('aq50-2')::uuid, 'dddddddd-0000-0000-0000-000000000002', 1, 'Prefiero hacer las cosas siempre de la misma manera.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Cambio Atencional / Flexibilidad', array['aq50','attention_switch']::text[]),
  (md5('aq50-3')::uuid, 'dddddddd-0000-0000-0000-000000000002', 2, 'Si intento imaginar algo, me resulta muy fácil crear la imagen en mi mente.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[]),
  (md5('aq50-4')::uuid, 'dddddddd-0000-0000-0000-000000000002', 3, 'Con frecuencia me involucro tanto en algo, que ignoro lo demás.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Cambio Atencional / Flexibilidad', array['aq50','attention_switch']::text[]),
  (md5('aq50-5')::uuid, 'dddddddd-0000-0000-0000-000000000002', 4, 'A menudo noto pequeños sonidos que los demás no perciben.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-6')::uuid, 'dddddddd-0000-0000-0000-000000000002', 5, 'Suelo fijarme en las placas de los automóviles, o en patrones de información de ese tipo.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-7')::uuid, 'dddddddd-0000-0000-0000-000000000002', 6, 'Muchas veces me dicen que lo que digo es poco amable, aunque yo crea que sí es amable.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-8')::uuid, 'dddddddd-0000-0000-0000-000000000002', 7, 'Cuando leo un cuento, me es fácil imaginar cómo se ven los personajes.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[]),
  (md5('aq50-9')::uuid, 'dddddddd-0000-0000-0000-000000000002', 8, 'Me fascina recordar fechas.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-10')::uuid, 'dddddddd-0000-0000-0000-000000000002', 9, 'En una situación social puedo seguir distintas conversaciones a la vez.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Cambio Atencional / Flexibilidad', array['aq50','attention_switch']::text[]),
  (md5('aq50-11')::uuid, 'dddddddd-0000-0000-0000-000000000002', 10, 'Las situaciones sociales se me facilitan.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
  (md5('aq50-12')::uuid, 'dddddddd-0000-0000-0000-000000000002', 11, 'Suelo notar detalles que los demás no ven.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-13')::uuid, 'dddddddd-0000-0000-0000-000000000002', 12, 'Prefiero ir a una biblioteca que a una fiesta.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
  (md5('aq50-14')::uuid, 'dddddddd-0000-0000-0000-000000000002', 13, 'Me es fácil inventar historias.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[]),
  (md5('aq50-15')::uuid, 'dddddddd-0000-0000-0000-000000000002', 14, 'Me llaman más la atención las personas que los objetos.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
  (md5('aq50-16')::uuid, 'dddddddd-0000-0000-0000-000000000002', 15, 'Hay cosas que suelen interesarme mucho, y me molesta cuando no puedo dedicarles tiempo.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Cambio Atencional / Flexibilidad', array['aq50','attention_switch']::text[]),
  (md5('aq50-17')::uuid, 'dddddddd-0000-0000-0000-000000000002', 16, 'Me gusta tener pláticas casuales.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-18')::uuid, 'dddddddd-0000-0000-0000-000000000002', 17, 'Cuando hablo, casi no dejo hablar a los demás.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-19')::uuid, 'dddddddd-0000-0000-0000-000000000002', 18, 'Me encantan los números.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-20')::uuid, 'dddddddd-0000-0000-0000-000000000002', 19, 'Cuando leo un cuento, me cuesta trabajo entender las intenciones de los personajes.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[]),
  (md5('aq50-21')::uuid, 'dddddddd-0000-0000-0000-000000000002', 20, 'No me gusta mucho leer temas de ficción.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[]),
  (md5('aq50-22')::uuid, 'dddddddd-0000-0000-0000-000000000002', 21, 'Me cuesta trabajo hacer nuevos amigos.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
  (md5('aq50-23')::uuid, 'dddddddd-0000-0000-0000-000000000002', 22, 'Siempre noto patrones o secuencias en las cosas.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-24')::uuid, 'dddddddd-0000-0000-0000-000000000002', 23, 'Prefiero ir al teatro que al museo.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[]),
  (md5('aq50-25')::uuid, 'dddddddd-0000-0000-0000-000000000002', 24, 'No me molesta cuando hay cambios en mi rutina diaria.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Cambio Atencional / Flexibilidad', array['aq50','attention_switch']::text[]),
  (md5('aq50-26')::uuid, 'dddddddd-0000-0000-0000-000000000002', 25, 'Por lo general me parece que no sé cómo mantener una conversación.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-27')::uuid, 'dddddddd-0000-0000-0000-000000000002', 26, 'Cuando alguien me está platicando, me parece fácil leer entre líneas o captar indirectas.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-28')::uuid, 'dddddddd-0000-0000-0000-000000000002', 27, 'A menudo me concentro más en lo general que en los pequeños detalles.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-29')::uuid, 'dddddddd-0000-0000-0000-000000000002', 28, 'No soy muy bueno para recordar números telefónicos.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-30')::uuid, 'dddddddd-0000-0000-0000-000000000002', 29, 'Usualmente, no me doy cuenta de cambios pequeños en una situación o en la apariencia de una persona.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-31')::uuid, 'dddddddd-0000-0000-0000-000000000002', 30, 'Me doy cuenta cuando alguien que me está escuchando, se aburre.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-32')::uuid, 'dddddddd-0000-0000-0000-000000000002', 31, 'Me parece fácil hacer más de una cosa a la vez.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Cambio Atencional / Flexibilidad', array['aq50','attention_switch']::text[]),
  (md5('aq50-33')::uuid, 'dddddddd-0000-0000-0000-000000000002', 32, 'Cuando hablo por teléfono, no sé bien cuándo es mi turno para hablar.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-34')::uuid, 'dddddddd-0000-0000-0000-000000000002', 33, 'Me gusta hacer las cosas sin planearlas mucho.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Cambio Atencional / Flexibilidad', array['aq50','attention_switch']::text[]),
  (md5('aq50-35')::uuid, 'dddddddd-0000-0000-0000-000000000002', 34, 'Suelo ser el último en entender una broma.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-36')::uuid, 'dddddddd-0000-0000-0000-000000000002', 35, 'Me es fácil darme cuenta de lo que alguien está pensando o sintiendo con tan sólo ver su rostro.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
