  (md5('aq50-38')::uuid, 'dddddddd-0000-0000-0000-000000000002', 37, 'Soy bueno para platicar sobre temas sin importancia.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-39')::uuid, 'dddddddd-0000-0000-0000-000000000002', 38, 'Me suelen decir que me la paso hablando sobre un mismo tema, una y otra vez.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Comunicación', array['aq50','communication']::text[]),
  (md5('aq50-40')::uuid, 'dddddddd-0000-0000-0000-000000000002', 39, 'De chico me gustaba actuar o fingir personajes cuando jugaba con otros niños.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[]),
  (md5('aq50-41')::uuid, 'dddddddd-0000-0000-0000-000000000002', 40, 'Me gusta recabar información relacionada con ciertas categorías de cosas (por ejemplo, tipos de automóviles, aves, teléfonos, plantas, etc.).', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[]),
  (md5('aq50-42')::uuid, 'dddddddd-0000-0000-0000-000000000002', 41, 'Me cuesta trabajo imaginar cómo sería ser otra persona.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[]),
  (md5('aq50-43')::uuid, 'dddddddd-0000-0000-0000-000000000002', 42, 'Me gusta planear cuidadosamente las actividades en las que participo.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Cambio Atencional / Flexibilidad', array['aq50','attention_switch']::text[]),
  (md5('aq50-44')::uuid, 'dddddddd-0000-0000-0000-000000000002', 43, 'Me gustan las actividades sociales.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
  (md5('aq50-45')::uuid, 'dddddddd-0000-0000-0000-000000000002', 44, 'Me cuesta trabajo entender las intenciones de las personas.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
  (md5('aq50-46')::uuid, 'dddddddd-0000-0000-0000-000000000002', 45, 'Las situaciones nuevas me ponen muy nervioso.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":1},{"text":"Un poco de acuerdo","score":1},{"text":"Un poco en desacuerdo","score":0},{"text":"Totalmente en desacuerdo","score":0}]}'::jsonb, 'Cambio Atencional / Flexibilidad', array['aq50','attention_switch']::text[]),
  (md5('aq50-47')::uuid, 'dddddddd-0000-0000-0000-000000000002', 46, 'Me gusta conocer gente nueva.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
  (md5('aq50-48')::uuid, 'dddddddd-0000-0000-0000-000000000002', 47, 'Soy bastante diplomático.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Habilidades Sociales', array['aq50','social']::text[]),
  (md5('aq50-49')::uuid, 'dddddddd-0000-0000-0000-000000000002', 48, 'No soy muy bueno para recordar la fecha de nacimiento de otras personas.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Atención al Detalle', array['aq50','attention_detail']::text[]),
  (md5('aq50-50')::uuid, 'dddddddd-0000-0000-0000-000000000002', 49, 'Me resulta muy fácil jugar a juegos con niños en los que hay que fingir ser otra persona.', '{"type":"likert","choices":[{"text":"Totalmente de acuerdo","score":0},{"text":"Un poco de acuerdo","score":0},{"text":"Un poco en desacuerdo","score":1},{"text":"Totalmente en desacuerdo","score":1}]}'::jsonb, 'Imaginación', array['aq50','imagination']::text[])
