insert into public.questions (id, exam_id, order_index, content, options, category, tags) values
  (md5('raadsr-1')::uuid, 'dddddddd-0000-0000-0000-000000000003', 0, 'Soy una persona comprensiva.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-2')::uuid, 'dddddddd-0000-0000-0000-000000000003', 1, 'A menudo uso palabras y frases de películas y televisión en las conversaciones.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Lenguaje y Comunicación', array['raadsr','language']::text[]),
  (md5('raadsr-3')::uuid, 'dddddddd-0000-0000-0000-000000000003', 2, 'A menudo me sorprende cuando los demás me dicen que he sido grosero.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-4')::uuid, 'dddddddd-0000-0000-0000-000000000003', 3, 'A veces hablo demasiado alto o demasiado bajo y no me doy cuenta.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Lenguaje y Comunicación', array['raadsr','language']::text[]),
  (md5('raadsr-5')::uuid, 'dddddddd-0000-0000-0000-000000000003', 4, 'A menudo no sé cómo actuar en situaciones sociales.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-6')::uuid, 'dddddddd-0000-0000-0000-000000000003', 5, 'Puedo ponerme en el lugar de otras personas.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-7')::uuid, 'dddddddd-0000-0000-0000-000000000003', 6, 'Me cuesta entender el significado de algunas frases hechas o metáforas (ej. ''eres la niña de mis ojos'').', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Lenguaje y Comunicación', array['raadsr','language']::text[]),
  (md5('raadsr-8')::uuid, 'dddddddd-0000-0000-0000-000000000003', 7, 'Solo me gusta hablar con personas que comparten mis intereses especiales.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-9')::uuid, 'dddddddd-0000-0000-0000-000000000003', 8, 'Me concentro en los detalles más que en la idea general.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-10')::uuid, 'dddddddd-0000-0000-0000-000000000003', 9, 'Siempre noto cómo se siente la comida en mi boca. La textura es más importante para mí que su sabor.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-11')::uuid, 'dddddddd-0000-0000-0000-000000000003', 10, 'Extraño a mis mejores amigos o familiares cuando estamos separados por mucho tiempo.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-12')::uuid, 'dddddddd-0000-0000-0000-000000000003', 11, 'A veces ofendo a los demás diciendo lo que pienso, aunque no sea mi intención.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-13')::uuid, 'dddddddd-0000-0000-0000-000000000003', 12, 'Solo me gusta pensar y hablar de algunas cosas muy específicas que me apasionan.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-14')::uuid, 'dddddddd-0000-0000-0000-000000000003', 13, 'Prefiero salir a comer solo a un restaurante que con un conocido.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-15')::uuid, 'dddddddd-0000-0000-0000-000000000003', 14, 'No puedo imaginar cómo sería ser otra persona.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-16')::uuid, 'dddddddd-0000-0000-0000-000000000003', 15, 'Me han dicho con frecuencia que soy torpe o descoordinado.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-17')::uuid, 'dddddddd-0000-0000-0000-000000000003', 16, 'Otros me consideran extraño, peculiar o diferente.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-18')::uuid, 'dddddddd-0000-0000-0000-000000000003', 17, 'Entiendo con facilidad cuando los amigos necesitan ser consolados.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-19')::uuid, 'dddddddd-0000-0000-0000-000000000003', 18, 'Soy muy sensible a cómo se siente mi ropa al tacto; la sensación es más importante que la apariencia.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-20')::uuid, 'dddddddd-0000-0000-0000-000000000003', 19, 'Me gusta copiar conscientemente la forma de hablar y actuar de otros para parecer más normal (camuflaje).', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-21')::uuid, 'dddddddd-0000-0000-0000-000000000003', 20, 'Puede ser muy intimidante o agotador hablar con más de una persona a la vez.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-22')::uuid, 'dddddddd-0000-0000-0000-000000000003', 21, 'Siento que tengo que ''actuar normal'' para complacer a los demás y encajar.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-23')::uuid, 'dddddddd-0000-0000-0000-000000000003', 22, 'Conocer gente nueva suele ser difícil para mí.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-24')::uuid, 'dddddddd-0000-0000-0000-000000000003', 23, 'Me confundo o enfurezco cuando alguien me interrumpe al hablar de algo que me interesa.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-25')::uuid, 'dddddddd-0000-0000-0000-000000000003', 24, 'Es difícil para mí entender cómo se sienten las demás personas mientras estamos conversando.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-26')::uuid, 'dddddddd-0000-0000-0000-000000000003', 25, 'Me gusta participar en conversaciones con varias personas en un grupo grande.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-27')::uuid, 'dddddddd-0000-0000-0000-000000000003', 26, 'Tomo las cosas demasiado literalmente, por lo que a menudo pierdo el doble sentido.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Lenguaje y Comunicación', array['raadsr','language']::text[]),
  (md5('raadsr-28')::uuid, 'dddddddd-0000-0000-0000-000000000003', 27, 'Es muy difícil para mí notar si alguien siente vergüenza o celos.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-29')::uuid, 'dddddddd-0000-0000-0000-000000000003', 28, 'Algunas texturas ordinarias que no molestan a otros se sienten insoportables en mi piel.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-30')::uuid, 'dddddddd-0000-0000-0000-000000000003', 29, 'Me enfado o angustio mucho cuando mi rutina diaria o la forma de hacer las cosas cambia repentinamente.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-31')::uuid, 'dddddddd-0000-0000-0000-000000000003', 30, 'Nunca he sentido la necesidad de tener lo que otros llaman una ''relación íntima''.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-32')::uuid, 'dddddddd-0000-0000-0000-000000000003', 31, 'Me cuesta iniciar y finalizar una conversación fluidamente; tiendo a alargarme hasta terminar todo.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-33')::uuid, 'dddddddd-0000-0000-0000-000000000003', 32, 'Hablo con un ritmo y entonación que otros consideran totalmente normal.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-34')::uuid, 'dddddddd-0000-0000-0000-000000000003', 33, 'Un sonido, color o textura puede pasar de fascinarme a causarme rechazo absoluto.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-35')::uuid, 'dddddddd-0000-0000-0000-000000000003', 34, 'Frases en sentido figurado me resultan confusas o incómodas.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-36')::uuid, 'dddddddd-0000-0000-0000-000000000003', 35, 'A veces el sonido de ciertas palabras o un ruido agudo me genera dolor físico en los oídos.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-37')::uuid, 'dddddddd-0000-0000-0000-000000000003', 36, 'Soy considerado un tipo de persona sumamente empática y comprensiva.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-38')::uuid, 'dddddddd-0000-0000-0000-000000000003', 37, 'No logro conectar con los personajes de las películas ni sentir lo que ellos sienten.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-39')::uuid, 'dddddddd-0000-0000-0000-000000000003', 38, 'No suelo darme cuenta cuando alguien está coqueteando conmigo.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
