  (md5('raadsr-41')::uuid, 'dddddddd-0000-0000-0000-000000000003', 40, 'Mantengo listas y datos detallados de cosas que me interesan (fechas, estadísticas, horarios, etc.).', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-42')::uuid, 'dddddddd-0000-0000-0000-000000000003', 41, 'Cuando me siento sobrecargado por mis sentidos, necesito aislarme por completo a oscuras.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-43')::uuid, 'dddddddd-0000-0000-0000-000000000003', 42, 'Disfruto charlar espontáneamente sobre temas triviales con conocidos.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-44')::uuid, 'dddddddd-0000-0000-0000-000000000003', 43, 'No puedo identificar si alguien está aburrido o interesado con lo que le estoy contando.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-45')::uuid, 'dddddddd-0000-0000-0000-000000000003', 44, 'Me cuesta leer el lenguaje corporal, expresiones faciales y gestos de las personas al hablar.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-46')::uuid, 'dddddddd-0000-0000-0000-000000000003', 45, 'La misma textura o temperatura puede sentirse insoportable en un momento y tolerable en otro.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Lenguaje y Comunicación', array['raadsr','language']::text[]),
  (md5('raadsr-47')::uuid, 'dddddddd-0000-0000-0000-000000000003', 46, 'Me siento muy cómodo y relajado en eventos sociales concurridos.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-48')::uuid, 'dddddddd-0000-0000-0000-000000000003', 47, 'Me esfuerzo activamente por dar consejos prácticos cuando otros me cuentan sus problemas personales.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-49')::uuid, 'dddddddd-0000-0000-0000-000000000003', 48, 'Me han señalado que mi tono de voz es peculiar (monótono, infantil, robótico o inusualmente agudo).', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-50')::uuid, 'dddddddd-0000-0000-0000-000000000003', 49, 'Un pensamiento o tema se atasca en mi cabeza y siento la imperiosa necesidad de verbalizarlo.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-51')::uuid, 'dddddddd-0000-0000-0000-000000000003', 50, 'Hago movimientos repetitivos con las manos o el cuerpo (aleteo, balanceo, girar objetos) para regularme.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-52')::uuid, 'dddddddd-0000-0000-0000-000000000003', 51, 'Mis gustos e intereses son muy diferentes a los de la mayoría de las personas de mi entorno.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
