  (md5('raadsr-59')::uuid, 'dddddddd-0000-0000-0000-000000000003', 58, 'Tengo un umbral atípico al dolor (puedo quemarme o golpearme y apenas sentir molestia inmediata).', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
