  (md5('raadsr-67')::uuid, 'dddddddd-0000-0000-0000-000000000003', 66, 'Lugares con exceso de olores intensos, luces parpadeantes y bullicio me provocan pánico o ganas de huir.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
