  (md5('raadsr-70')::uuid, 'dddddddd-0000-0000-0000-000000000003', 69, 'Organizo mis recuerdos en mi mente como ficheros o mapas visuales ordenados minuciosamente.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Intereses Circunscritos', array['raadsr','interests']::text[]),
  (md5('raadsr-71')::uuid, 'dddddddd-0000-0000-0000-000000000003', 70, 'La intensidad de un sonido puede resultarme ensordecedora aunque el volumen no haya cambiado.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-72')::uuid, 'dddddddd-0000-0000-0000-000000000003', 71, 'Me resulta fácil integrarme a reuniones familiares o fiestas sin sentirme desubicado.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-73')::uuid, 'dddddddd-0000-0000-0000-000000000003', 72, 'Tengo una alta tolerancia y me adapto sin problemas a olores o sabores que no me agradan.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Lenguaje y Comunicación', array['raadsr','language']::text[]),
  (md5('raadsr-74')::uuid, 'dddddddd-0000-0000-0000-000000000003', 73, 'No me gusta el contacto físico imprevisto (abrazos, palmadas en la espalda, caricias).', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-75')::uuid, 'dddddddd-0000-0000-0000-000000000003', 74, 'Necesito seguir trayectos y rutas conocidas; desviarme me genera gran ansiedad y desorientación.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-76')::uuid, 'dddddddd-0000-0000-0000-000000000003', 75, 'Me cuesta descifrar lo que los demás esperan de mí en situaciones laborales o informales.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-77')::uuid, 'dddddddd-0000-0000-0000-000000000003', 76, 'Tengo un grupo sólido y cercano de amigos íntimos con quienes me comunico frecuentemente.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":0},{"text":"Verdad, solo ahora","score":1},{"text":"Verdad, solo cuando tenía < 16 años","score":2},{"text":"La verdad, nunca","score":3}]}'::jsonb, 'Relaciones Sociales', array['raadsr','social']::text[]),
  (md5('raadsr-78')::uuid, 'dddddddd-0000-0000-0000-000000000003', 77, 'Las personas me dicen que suelo dar explicaciones con un nivel excesivo e innecesario de detalles.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Procesamiento Sensorial-Motor', array['raadsr','sensory']::text[]),
  (md5('raadsr-79')::uuid, 'dddddddd-0000-0000-0000-000000000003', 78, 'A menudo hago preguntas que a los demás les parecen indiscretas o socialmente inadecuadas.', '{"type":"single_choice","choices":[{"text":"Verdad, ahora y cuando era joven","score":3},{"text":"Verdad, solo ahora","score":2},{"text":"Verdad, solo cuando tenía < 16 años","score":1},{"text":"La verdad, nunca","score":0}]}'::jsonb, 'Lenguaje y Comunicación', array['raadsr','language']::text[]),
