  (md5('conners4-1')::uuid, 'dddddddd-0000-0000-0000-000000000005', 0, 'Se distrae fácilmente ante ruidos, movimientos u otros estímulos.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Inatención', array['conners4','inattention']::text[]),
  (md5('conners4-2')::uuid, 'dddddddd-0000-0000-0000-000000000005', 1, 'Le cuesta trabajo ponerse a trabajar de nuevo cuando lo interrumpen.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Función Ejecutiva', array['conners4','executive']::text[]),
  (md5('conners4-3')::uuid, 'dddddddd-0000-0000-0000-000000000005', 2, 'No logra seguir instrucciones y no finaliza las tareas o deberes.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Inatención', array['conners4','inattention']::text[]),
  (md5('conners4-4')::uuid, 'dddddddd-0000-0000-0000-000000000005', 3, 'Le cuesta trabajo concentrarse en una sola actividad.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Inatención', array['conners4','inattention']::text[]),
  (md5('conners4-5')::uuid, 'dddddddd-0000-0000-0000-000000000005', 4, 'Es impulsivo/a (actúa antes de pensar en las consecuencias).', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Impulsividad', array['conners4','impulsivity']::text[]),
  (md5('conners4-6')::uuid, 'dddddddd-0000-0000-0000-000000000005', 5, 'Le cuesta trabajo organizar sus tareas, materiales escolares o actividades.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Función Ejecutiva', array['conners4','executive']::text[]),
  (md5('conners4-7')::uuid, 'dddddddd-0000-0000-0000-000000000005', 6, 'Tiene un periodo de atención muy corto o no mantiene el enfoque.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Inatención', array['conners4','inattention']::text[]),
  (md5('conners4-8')::uuid, 'dddddddd-0000-0000-0000-000000000005', 7, 'Se le dificulta asignar prioridad a las tareas o planificar con tiempo.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Función Ejecutiva', array['conners4','executive']::text[]),
  (md5('conners4-9')::uuid, 'dddddddd-0000-0000-0000-000000000005', 8, 'Le cuesta trabajo cambiar de una tarea a otra (rigidez en transiciones).', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Función Ejecutiva', array['conners4','executive']::text[]),
  (md5('conners4-10')::uuid, 'dddddddd-0000-0000-0000-000000000005', 9, 'No puede estarse quieto/a o le resulta imposible relajarse.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Hiperactividad', array['conners4','hyperactivity']::text[]),
  (md5('conners4-11')::uuid, 'dddddddd-0000-0000-0000-000000000005', 10, 'Le cuesta trabajo concentrarse por mucho tiempo seguido al trabajar o jugar.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Inatención', array['conners4','inattention']::text[]),
  (md5('conners4-12')::uuid, 'dddddddd-0000-0000-0000-000000000005', 11, 'Comete errores por no revisar ni prestar atención a los detalles.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Inatención', array['conners4','inattention']::text[]),
  (md5('conners4-13')::uuid, 'dddddddd-0000-0000-0000-000000000005', 12, 'Mueve continuamente los dedos, manos, pies o se retuerce en el asiento.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Hiperactividad', array['conners4','hyperactivity']::text[]),
  (md5('conners4-14')::uuid, 'dddddddd-0000-0000-0000-000000000005', 13, 'Se levanta con frecuencia en situaciones donde debería estar sentado.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Hiperactividad', array['conners4','hyperactivity']::text[]),
  (md5('conners4-15')::uuid, 'dddddddd-0000-0000-0000-000000000005', 14, 'Corre o trepa en exceso en lugares inadecuados.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Hiperactividad', array['conners4','hyperactivity']::text[]),
  (md5('conners4-16')::uuid, 'dddddddd-0000-0000-0000-000000000005', 15, 'Habla de forma excesiva e ininterrumpida.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Hiperactividad', array['conners4','hyperactivity']::text[]),
  (md5('conners4-17')::uuid, 'dddddddd-0000-0000-0000-000000000005', 16, 'Responde precipitadamente antes de que se hayan terminado de formular las preguntas.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Impulsividad', array['conners4','impulsivity']::text[]),
