  (md5('conners4-21')::uuid, 'dddddddd-0000-0000-0000-000000000005', 20, 'Parece no escuchar cuando se le habla directamente.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Inatención', array['conners4','inattention']::text[]),
  (md5('conners4-22')::uuid, 'dddddddd-0000-0000-0000-000000000005', 21, 'Es olvidadizo/a en las actividades y rutinas cotidianas.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Inatención', array['conners4','inattention']::text[]),
  (md5('conners4-23')::uuid, 'dddddddd-0000-0000-0000-000000000005', 22, 'Evita o muestra fuerte resistencia ante tareas que requieren esfuerzo mental sostenido.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Función Ejecutiva', array['conners4','executive']::text[]),
  (md5('conners4-24')::uuid, 'dddddddd-0000-0000-0000-000000000005', 23, 'Está siempre en marcha, actuando como si tuviera un "motor".', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Hiperactividad', array['conners4','hyperactivity']::text[]),
  (md5('conners4-25')::uuid, 'dddddddd-0000-0000-0000-000000000005', 24, 'Le cuesta trabajo jugar o dedicarse tranquilamente a actividades de ocio.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Hiperactividad', array['conners4','hyperactivity']::text[]),
  (md5('conners4-26')::uuid, 'dddddddd-0000-0000-0000-000000000005', 25, 'Tiene explosiones impredecibles de mal genio o berrinches intensos.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Emocional', array['conners4','emotional']::text[]),
  (md5('conners4-27')::uuid, 'dddddddd-0000-0000-0000-000000000005', 26, 'Cambia bruscamente de estado de ánimo ante pequeñas frustraciones.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Emocional', array['conners4','emotional']::text[]),
  (md5('conners4-28')::uuid, 'dddddddd-0000-0000-0000-000000000005', 27, 'Es irritable, susceptible o se molesta fácilmente con otros.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Emocional', array['conners4','emotional']::text[]),
  (md5('conners4-29')::uuid, 'dddddddd-0000-0000-0000-000000000005', 28, 'Sus esfuerzos se frustran con rapidez y se rinde de inmediato.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Emocional', array['conners4','emotional']::text[]),
  (md5('conners4-30')::uuid, 'dddddddd-0000-0000-0000-000000000005', 29, 'Discute y desafía activamente las peticiones o reglas de los adultos.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Oposicionismo', array['conners4','oppositional']::text[]),
  (md5('conners4-31')::uuid, 'dddddddd-0000-0000-0000-000000000005', 30, 'Rehúsa obedecer o cumple con evidente desgana y protestas.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Oposicionismo', array['conners4','oppositional']::text[]),
  (md5('conners4-32')::uuid, 'dddddddd-0000-0000-0000-000000000005', 31, 'Molesta deliberadamente a otras personas o a sus hermanos.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Oposicionismo', array['conners4','oppositional']::text[]),
  (md5('conners4-33')::uuid, 'dddddddd-0000-0000-0000-000000000005', 32, 'Culpa a otros por sus propios errores o por su mala conducta.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Oposicionismo', array['conners4','oppositional']::text[]),
  (md5('conners4-34')::uuid, 'dddddddd-0000-0000-0000-000000000005', 33, 'Se muestra rencoroso/a o vengativo/a cuando se le corrige.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Emocional', array['conners4','emotional']::text[]),
  (md5('conners4-35')::uuid, 'dddddddd-0000-0000-0000-000000000005', 34, 'Tiene problemas para estimar cuánto tiempo le tomará completar una tarea.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Función Ejecutiva', array['conners4','executive']::text[]),
  (md5('conners4-36')::uuid, 'dddddddd-0000-0000-0000-000000000005', 35, 'Inicia múltiples proyectos o tareas simultáneas sin terminar ninguna.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Función Ejecutiva', array['conners4','executive']::text[]),
  (md5('conners4-37')::uuid, 'dddddddd-0000-0000-0000-000000000005', 36, 'Olvida el paso siguiente cuando realiza instrucciones compuestas.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Función Ejecutiva', array['conners4','executive']::text[]),
  (md5('conners4-38')::uuid, 'dddddddd-0000-0000-0000-000000000005', 37, 'Hace comentarios inapropiados sin filtros sociales previos.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Impulsividad', array['conners4','impulsivity']::text[]),
  (md5('conners4-39')::uuid, 'dddddddd-0000-0000-0000-000000000005', 38, 'Emite ruidos molestos en momentos o lugares donde se requiere silencio.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Hiperactividad', array['conners4','hyperactivity']::text[]),
  (md5('conners4-40')::uuid, 'dddddddd-0000-0000-0000-000000000005', 39, 'Se precipita en situaciones peligrosas sin evaluar el riesgo físico.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Impulsividad', array['conners4','impulsivity']::text[]),
  (md5('conners4-41')::uuid, 'dddddddd-0000-0000-0000-000000000005', 40, 'Reacciona de forma desproporcionada ante cambios imprevistos de planes.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Emocional', array['conners4','emotional']::text[]),
  (md5('conners4-42')::uuid, 'dddddddd-0000-0000-0000-000000000005', 41, 'Olvida guardar o devolver materiales y pertenencias.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Función Ejecutiva', array['conners4','executive']::text[]),
  (md5('conners4-43')::uuid, 'dddddddd-0000-0000-0000-000000000005', 42, 'Presenta dificultades persistentes en el rendimiento escolar a causa de la falta de concentración.', '{"type":"likert","choices":[{"text":"Nada cierto (Nunca / Rara vez)","score":0},{"text":"Un poco cierto (Ocasionalmente)","score":1},{"text":"Bastante cierto (A menudo / Frecuentemente)","score":2},{"text":"Muy cierto (Muy a menudo / Siempre)","score":3}]}'::jsonb, 'Inatención', array['conners4','inattention']::text[])
insert into public.diagnostic_rules (id, exam_id, name, min_score, max_score, min_age, max_age, subcategory, recommendations, is_active) values
  (md5('conners4-rule-1')::uuid, 'dddddddd-0000-0000-0000-000000000005', 'Promedio para la edad (Conners 4, bruto 0 a 34)', 0, 34, 6, 18, 'Promedio para la edad (Conners 4, bruto 0 a 34)', '["Conducta dentro de lo esperado en casa."]'::jsonb, true),
  (md5('conners4-rule-2')::uuid, 'dddddddd-0000-0000-0000-000000000005', 'Rango límite (Conners 4, bruto 35 a 44)', 35, 44, 6, 18, 'Rango límite (Conners 4, bruto 35 a 44)', '["Seguimiento; pedir escala del docente para contrastar entornos."]'::jsonb, true),
  (md5('conners4-rule-3')::uuid, 'dddddddd-0000-0000-0000-000000000005', 'Elevado (Conners 4, bruto 45 a 59)', 45, 59, 6, 18, 'Elevado (Conners 4, bruto 45 a 59)', '["Evaluación de TDAH con entrevista clínica y pruebas de atención (D2-R, Stroop)."]'::jsonb, true),
  (md5('conners4-rule-4')::uuid, 'dddddddd-0000-0000-0000-000000000005', 'Muy elevado (Conners 4, bruto 60 o más)', 60, 129, 6, 18, 'Muy elevado (Conners 4, bruto 60 o más)', '["Evaluación prioritaria de TDAH y problemas asociados de conducta."]'::jsonb, true)
insert into public.exams (id, title, description, created_by, is_published)
insert into public.questions (id, exam_id, order_index, content, options, category, tags) values
  (md5('cars2-1')::uuid, 'dddddddd-0000-0000-0000-000000000006', 0, '1. Relación con las Personas: Evalúa la calidez, contacto afectivo, interés social e interacción recíproca con el evaluador, padres y otros niños.', '{"type":"single_choice","choices":[{"text":"1. Conducta apropiada para la edad. Muestra timidez o afecto normal, busca consuelo e interactúa espontáneamente con interés mutuo.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Puede evitar contacto ocular de forma intermitente, mostrar timidez excesiva o responder con cierta lentitud a las aproximaciones sociales.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Se muestra distante o indiferente gran parte del tiempo. Cuesta captar su atención; a veces parece ignorar a las personas o requiere esfuerzo intenso para interactuar.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Profundamente aislado y desvinculado del entorno humano. No responde a intentos de contacto, actúa como si los demás no existieran o los utiliza como meros instrumentos físicos.","score":8}]}'::jsonb, 'Relación Social', array['cars2','observación']::text[]),
  (md5('cars2-2')::uuid, 'dddddddd-0000-0000-0000-000000000006', 1, '2. Imitación: Evalúa la capacidad espontánea y provocada para reproducir sonidos, palabras, gestos y secuencias de acción motora.', '{"type":"single_choice","choices":[{"text":"1. Imitación adecuada. Imita sonidos, palabras y movimientos motores simples o complejos apropiados a su nivel madurativo.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Imita conductas sencillas la mayor parte del tiempo, pero puede necesitar insistencia o presentar un ligero retraso en la ejecución.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Solo imita parte del tiempo o requiere considerable ayuda y estructuración; la imitación suele ser fragmentaria o mecánica.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Rara vez o nunca imita sonidos, palabras o movimientos ajenos, aun ante incitación directa y reforzamiento estructurado.","score":8}]}'::jsonb, 'Imitación', array['cars2','observación']::text[]),
  (md5('cars2-3')::uuid, 'dddddddd-0000-0000-0000-000000000006', 2, '3. Respuesta Emocional: Evalúa la adecuación, variedad y congruencia de las expresiones de alegría, tristeza, enfado o ansiedad frente al contexto.', '{"type":"single_choice","choices":[{"text":"1. Respuesta emocional adecuada. El tipo y grado de afecto manifestado concuerda con las situaciones cotidianas placenteras o frustrantes.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Reacciones emocionales algo exageradas o amortiguadas; ligeros desfases entre la expresión y el estímulo desencadenante.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Muestra signos claros de respuesta afectiva inapropiada (risas sin motivo aparente, rigidez emocional o rabietas de difícil calma ante eventos menores).","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Emociones sumamente atípicas y extremas sin relación aparente con el entorno, o absoluta falta de reactividad afectiva.","score":8}]}'::jsonb, 'Respuesta Emocional', array['cars2','observación']::text[]),
  (md5('cars2-4')::uuid, 'dddddddd-0000-0000-0000-000000000006', 3, '4. Uso del Cuerpo: Evalúa la motricidad, coordinación, presencia de estereotipias motoras (aleteo, balanceo, giros) o posturas atípicas.', '{"type":"single_choice","choices":[{"text":"1. Uso del cuerpo apropiado a la edad. Movimientos coordinados, marcha típica y ausencia de manierismos motores repetitivos.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Torpeza motora leve o manierismos repetitivos ocasionales (movimientos de dedos o postura tensa en momentos de excitación).","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Conductas motoras estereotipadas frecuentes y evidentes: aleteo de manos, balanceo corporal, marcha de puntillas o giros sobre sí mismo.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Movimientos corporales estereotipados intensos y persistentes que dominan la conducta del individuo y dificultan la realización de actividades.","score":8}]}'::jsonb, 'Uso del Cuerpo', array['cars2','observación']::text[]),
  (md5('cars2-5')::uuid, 'dddddddd-0000-0000-0000-000000000006', 4, '5. Uso de Objetos y Juego: Evalúa el interés, imaginación y funcionalidad en el manejo de juguetes y objetos cotidianos frente a fijaciones mecánicas.', '{"type":"single_choice","choices":[{"text":"1. Uso e interés adecuado por objetos. Juego funcional y simbólico acorde a la edad; exploración flexible y constructiva de juguetes.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Interés por objetos algo restringido; puede jugar de manera algo repetitiva o mostrar preferencia por detalles secundarios.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Poco interés en el uso funcional de los juguetes; conductas repetitivas marcadas (alinear objetos, girar ruedas, encender/apagar luces).","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Manipulación exclusivamente sensorial y repetitiva de partes de objetos; fijación obsesiva y resistencia extrema a utilizar los objetos funcionalmente.","score":8}]}'::jsonb, 'Uso de Objetos', array['cars2','observación']::text[]),
  (md5('cars2-6')::uuid, 'dddddddd-0000-0000-0000-000000000006', 5, '6. Adaptación al Cambio: Evalúa la flexibilidad ante modificaciones de rutinas, cambios de actividad, traslados o variaciones del entorno.', '{"type":"single_choice","choices":[{"text":"1. Adaptación adecuada. Tolera y asimila los cambios de actividades y rutinas sin angustia excesiva.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Muestra cierta resistencia inicial ante cambios imprevistos, pero se calma con apoyo o explicaciones del adulto.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Resistencia notable ante modificaciones en rutinas; angustia, enfado o negativismo evidente ante cambios de itinerario o disposición.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Reacciones de pánico, rabietas severas o desesperación extrema ante cualquier alteración de su rutina o entorno físico; insistencia rígida en la monotonía.","score":8}]}'::jsonb, 'Adaptación al Cambio', array['cars2','observación']::text[]),
  (md5('cars2-7')::uuid, 'dddddddd-0000-0000-0000-000000000006', 6, '7. Respuesta Visual: Evalúa el contacto ocular, seguimiento de miradas, fijación en luces o patrones y uso de visión periférica.', '{"type":"single_choice","choices":[{"text":"1. Respuesta visual adecuada. Contacto visual recíproco, natural y modulado; utiliza la mirada para comunicarse y explorar el entorno.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Contacto ocular intermitente o esquivo; puede mirar de reojo o fascinarse ocasionalmente por reflejos de luz.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Evitación visual frecuente; requiere recordatorios constantes para mirar; inspección de objetos muy cerca de los ojos o fijación atípica.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Evitación sistemática del contacto visual; mira a través de las personas o presenta fascinación visual obsesiva y persistente.","score":8}]}'::jsonb, 'Respuesta Visual', array['cars2','observación']::text[]),
  (md5('cars2-8')::uuid, 'dddddddd-0000-0000-0000-000000000006', 7, '8. Respuesta Auditiva (Escucha): Evalúa la reactividad ante la voz humana, ruidos del ambiente e hipo o hipersensibilidad a los sonidos.', '{"type":"single_choice","choices":[{"text":"1. Respuesta auditiva adecuada. Responde a su nombre y a sonidos ambientales habituales de manera esperada para su edad.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Puede tardar en responder al nombre en ocasiones o mostrar cierta molestia ante ruidos fuertes y súbitos.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Actúa con frecuencia como si estuviera sordo ante la voz humana; o bien muestra hiperacusia marcada (taparse los oídos ante sonidos comunes).","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Desconexión auditiva extrema ante llamados verbales combinada con hipersensibilidad fóbica ante sonidos específicos cotidianos.","score":8}]}'::jsonb, 'Respuesta Auditiva', array['cars2','observación']::text[]),
  (md5('cars2-9')::uuid, 'dddddddd-0000-0000-0000-000000000006', 8, '9. Respuesta y Uso del Gusto, Olfato y Tacto: Evalúa el procesamiento sensorial táctil, olfativo y gustativo (oler objetos no comestibles, selectividad alimentaria extrema, textura).', '{"type":"single_choice","choices":[{"text":"1. Uso sensorial apropiado. Explora objetos por el tacto adecuadamente y tolera texturas, sabores y temperaturas normales.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Muestra predilección por tocar ciertas texturas o rechazo leve a ensuciarse las manos o probar alimentos nuevos.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Huele o chupa objetos continuamente; aversión táctil marcada ante prendas o sustancias cotidianas; selectividad alimentaria estricta.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Fascinación sensorial obsesiva por oler y saborear todo tipo de objetos; respuestas extremas de dolor o placer táctil descontextualizadas.","score":8}]}'::jsonb, 'Gusto, Olfato y Tacto', array['cars2','observación']::text[]),
  (md5('cars2-10')::uuid, 'dddddddd-0000-0000-0000-000000000006', 9, '10. Miedo o Ansiedad: Evalúa la presencia de temores irracionales o atípicos, así como la ausencia de conciencia ante peligros reales.', '{"type":"single_choice","choices":[{"text":"1. Miedo y ansiedad normales. Conducta proporcionada ante situaciones amenazantes y precaución razonable ante peligros.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Temor excesivo ocasional ante estímulos inofensivos o descuido ligero ante situaciones de riesgo.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Miedos intensos e irracionales difíciles de calmar (ej. a un electrodoméstico) o llamativa falta de conciencia ante riesgos graves (cruzar calles, alturas).","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Terrores persistentes generalizados sin causa aparente o total incapacidad para reconocer y evitar situaciones de peligro vital.","score":8}]}'::jsonb, 'Miedo / Ansiedad', array['cars2','observación']::text[]),
  (md5('cars2-11')::uuid, 'dddddddd-0000-0000-0000-000000000006', 10, '11. Comunicación Verbal: Evalúa el desarrollo del lenguaje hablado, vocabulario, sintaxis, ecolalia (inmediata o diferida), entonación y pragmática.', '{"type":"single_choice","choices":[{"text":"1. Comunicación verbal adecuada. Habla inteligible, vocabulario acorde a la edad y uso funcional y conversacional del lenguaje.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Ligero retraso en el lenguaje, frases sencillas o ecolalia ocasional sin afectar significativamente la comprensión básica.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Ausencia de lenguaje propositivo o uso predominante de ecolalias inmediatas/diferidas, inversión pronominal y entonación monótona o cantarina.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Ausencia total de lenguaje verbal funcional; emisión exclusiva de ruidos guturales, chillidos repetitivos o jerga ininteligible.","score":8}]}'::jsonb, 'Comunicación Verbal', array['cars2','observación']::text[]),
  (md5('cars2-12')::uuid, 'dddddddd-0000-0000-0000-000000000006', 11, '12. Comunicación No Verbal: Evalúa el uso de gestos comunicativos, señalamiento con el dedo índice (protoimperativo y protodeclarativo) y expresión corporal.', '{"type":"single_choice","choices":[{"text":"1. Comunicación no verbal adecuada. Señala con el índice para compartir interés o pedir, asiente/niega con la cabeza y utiliza gestos expresivos acordes.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Uso inmaduro de gestos; señala principalmente para pedir objetos pero poco para compartir atención; expresión facial algo inexpresiva.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Rara vez usa gestos comunicativos; suele tomar la mano del adulto como herramienta física sin mirar a su rostro.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Ausencia total de gestos comunicativos intencionales; incapacidad para interpretar las expresiones y posturas corporales de otros.","score":8}]}'::jsonb, 'Comunicación No Verbal', array['cars2','observación']::text[]),
  (md5('cars2-13')::uuid, 'dddddddd-0000-0000-0000-000000000006', 12, '13. Nivel de Actividad: Evalúa la regulación psicomotora (hiperactividad incesante, letargo/pasividad o alternancia extrema entre ambos).', '{"type":"single_choice","choices":[{"text":"1. Nivel de actividad apropiado. Alterna periodos de actividad y descanso con facilidad según el contexto.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Ligeramente inquieto o algo lento de movimientos, pero responde a la redirección del adulto.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Muy inquieto e hiperactivo, moviéndose continuamente sin propósito claro; o bien notablemente letárgico y difícil de activar.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Niveles extremos de agitación psicomotora difícilmente controlables o pasividad casi total e inmóvil.","score":8}]}'::jsonb, 'Nivel de Actividad', array['cars2','observación']::text[]),
  (md5('cars2-14')::uuid, 'dddddddd-0000-0000-0000-000000000006', 13, '14. Nivel y Consistencia de la Respuesta Intelectual: Evalúa la coherencia de las habilidades cognitivas (perfil armónico vs picos aislados de habilidad como memoria mecánica, cálculo o música).', '{"type":"single_choice","choices":[{"text":"1. Función intelectual armónica. Las habilidades cognitivas se encuentran homogéneamente desarrolladas en consonancia con la edad.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Ligeramente anormal. Rendimiento ligeramente irregular en algunas áreas no verbales o verbales, pero sin discrepancias extremas.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Moderadamente anormal. Perfil cognitivo muy disarmónico; retraso marcado en razonamiento general junto con destrezas aisladas en áreas específicas (memoria visoespacial, puzzles).","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Severamente anormal. Marcado desnivel intelectual; retraso severo en la mayoría de funciones adaptativas con habilidades islote (\"savants\") llamativas y muy especializadas.","score":8}]}'::jsonb, 'Perfil Intelectual', array['cars2','observación']::text[]),
  (md5('cars2-15')::uuid, 'dddddddd-0000-0000-0000-000000000006', 14, '15. Impresiones Generales: Juicio clínico global del evaluador integrando todas las observaciones conductuales directas e indirectas del paciente.', '{"type":"single_choice","choices":[{"text":"1. Sin síntomas de autismo. Ninguno de los síntomas observados es característico de un trastorno del espectro autista.","score":2},{"text":"1.5 - Levemente entre normal y ligeramente anormal","score":3},{"text":"2. Autismo leve. El paciente presenta un número reducido de síntomas o un grado leve de conductas del espectro autista.","score":4},{"text":"2.5 - Entre ligeramente y moderadamente anormal","score":5},{"text":"3. Autismo moderado. El paciente presenta un número claro y manifiesto de síntomas característicos de severidad moderada.","score":6},{"text":"3.5 - Entre moderadamente y severamente anormal","score":7},{"text":"4. Autismo severo. El paciente presenta síntomas múltiples, intensos y generalizados característicos del autismo grave.","score":8}]}'::jsonb, 'Impresión Global', array['cars2','observación']::text[])
insert into public.diagnostic_rules (id, exam_id, name, min_score, max_score, min_age, max_age, subcategory, recommendations, is_active) values
  (md5('cars2-rule-1')::uuid, 'dddddddd-0000-0000-0000-000000000006', 'Sin síntomas significativos de TEA (CARS-2 15 a 29.5)', 30, 59, 2, 99, 'Sin síntomas significativos de TEA (CARS-2 15 a 29.5)', '["Por debajo del punto de corte clínico."]'::jsonb, true),
  (md5('cars2-rule-2')::uuid, 'dddddddd-0000-0000-0000-000000000006', 'TEA leve a moderado (CARS-2 30 a 36.5)', 60, 73, 2, 99, 'TEA leve a moderado (CARS-2 30 a 36.5)', '["Integrar con historia del desarrollo y tamizajes previos.","Plan de intervención temprana: lenguaje, terapia ocupacional e intervención conductual."]'::jsonb, true),
  (md5('cars2-rule-3')::uuid, 'dddddddd-0000-0000-0000-000000000006', 'TEA severo (CARS-2 37 o más)', 74, 120, 2, 99, 'TEA severo (CARS-2 37 o más)', '["Intervención intensiva y coordinación con neuropediatría."]'::jsonb, true)
